<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$q=trim($_GET['q']??'');$page=max(1,(int)($_GET['page']??1));$size=8;$where='';$params=[];if($q!==''){$where=' WHERE full_name LIKE ? OR email LIKE ? OR role LIKE ?';$v='%'.$q.'%';$params=[$v,$v,$v];}$s=db()->prepare('SELECT COUNT(*) FROM users'.$where);$s->execute($params);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$size));$page=min($page,$pages);$s=db()->prepare('SELECT id,full_name,email,phone,role,created_at FROM users'.$where.' ORDER BY created_at DESC LIMIT '.$size.' OFFSET '.(($page-1)*$size));$s->execute($params);$rows=$s->fetchAll();render_header('User management');?><section class="heading"><div><p class="eyebrow">ADMINISTRATION</p><h1>User management</h1><p class="muted">Create, view, update, and delete records.</p></div><a class="btn" href="<?=e(BASE_URL)?>/admin/user-form.php">+ Add user</a></section><section class="panel table-panel"><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search name, email or role"><button class="btn secondary">Search</button><?php if($q!==''):?><a href="users.php">Clear</a><?php endif;?></form><div class="table-wrap"><table><thead><tr><th>User</th><th>Contact</th><th>Role</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['full_name'])?></b><small>ID #<?=$r['id']?></small></td><td><?=e($r['email'])?><small><?=e($r['phone']?:'No phone')?></small></td><td><span class="pill"><?=e(ucfirst($r['role']))?></span></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td><td class="actions"><a href="<?=e(BASE_URL)?>/admin/user-form.php?id=<?=$r['id']?>">Edit</a><?php if((int)$r['id']!==(int)current_user()['id']):?><form method="post" action="<?=e(BASE_URL)?>/admin/delete-user.php" data-confirm="Delete this user? This cannot be undone."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link-danger">Delete</button></form><?php else:?><small>You</small><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No users found.</td></tr><?php endif;?></tbody></table></div><div class="table-bottom"><span><?=$total?> users · Page <?=$page?>/<?=$pages?></span><div><?php if($page>1):?><a href="?q=<?=urlencode($q)?>&page=<?=$page-1?>">← Previous</a><?php endif;?> <?php if($page<$pages):?><a href="?q=<?=urlencode($q)?>&page=<?=$page+1?>">Next →</a><?php endif;?></div></div></section><?php render_footer();?>
